/* tools/toyc/toy_sound.h — the native sound calls (docs/NATIVE-SOUND.md,
 * option C).  The generated C calls toy_sound_boot() first in toy_boot() and
 * toy_sound_tick() before frame() each toy frame, and music()/sfx()/release()/
 * note() lower to the four calls below.  They are thin wrappers around the
 * interpreter ROM's sound glue (tools/ilvm/hutrack_engine.asm), which lives in
 * the engine's tables bank and is called by fixed address (hutrack-symbols.h,
 * generated by tools/ilvm/build-engine.sh), exactly as tools/ilvm/ilvm_sound.c
 * does; the PSG writes are therefore the interpreter's, and tests prove them
 * against the studio's.  The ROM layout it assumes (tools/build-toyc-banked.sh
 * with SOUND): physical bank 2 = engine code (page 5), 3 = pitch tables and the
 * glue (page 4), 4 = the song bank with its trailer (page 2).
 */
#ifndef TOY_SOUND_H
#define TOY_SOUND_H
#include <stdint.h>

void toy_sound_boot(void);
void toy_sound_tick(void);
int32_t toy_note(int32_t midi);
void toy_sfx(int32_t ch, int32_t freq, int32_t volume, int32_t frames);
void toy_sfx_fx(int32_t ch, int32_t wave, int32_t from, int32_t to,
                int32_t volume, int32_t attack, int32_t decay, int32_t frames);
void toy_release(int32_t ch);
void toy_music(int32_t song);
/* sample(name, channel): DDA playback from the timer interrupt (TOY_SAMPLE_BUILD, docs/NATIVE-SOUND.md) */
void toy_sample(int32_t ref, int32_t ch);

#endif
